+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Deliberately in-memory: messages are shared by all visits while the
+ * application is running, without introducing persistence for this example.
+ */
+@Service
+public class MessageStore {
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+}
